package com.primehr.performancemanagement.api;import com.primehr.performancemanagement.api.PerformanceInterventionDtos.*;import com.primehr.performancemanagement.application.PerformanceInterventionService;import com.primehr.security.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController@RequestMapping("/api/primehr/v1/performance-management")public class PerformanceInterventionController{private final PerformanceInterventionService service;private final PerformanceInterventionPermissionGuard permission;private final AgencyScopeResolver agency;public PerformanceInterventionController(PerformanceInterventionService s,PerformanceInterventionPermissionGuard p,AgencyScopeResolver a){service=s;permission=p;agency=a;}private static String actor(Authentication a){if(a==null||a.getName()==null||a.getName().isBlank())throw new org.springframework.security.access.AccessDeniedException("Authenticated employee identity is required");return a.getName();}
 @PostMapping("/intervention-rules")@ResponseStatus(HttpStatus.CREATED)public RuleResponse rule(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@Valid@RequestBody RuleInput r){permission.require(PrimeHrAction.ADD,t);return service.createRule(agency.resolveAgencyId(a),r,actor(a),c);}@GetMapping("/intervention-rules")public List<RuleResponse>rules(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t){permission.require(PrimeHrAction.ACCESS,t);return service.rules(agency.resolveAgencyId(a));}
 @GetMapping("/interventions")public List<InterventionResponse>list(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t){return service.list(agency.resolveAgencyId(a),actor(a),permission.require(PrimeHrAction.ACCESS,t));}@PostMapping("/interventions/{id}/issue")public InterventionResponse issue(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody IssueInput r){return service.issue(agency.resolveAgencyId(a),id,r,actor(a),permission.require(PrimeHrAction.SUBMIT,t),c);}@PostMapping("/interventions/{id}/acknowledge")public InterventionResponse acknowledge(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody AcknowledgeInput r){return service.acknowledge(agency.resolveAgencyId(a),id,r,actor(a),permission.require(PrimeHrAction.SUBMIT,t),c);}@PostMapping("/interventions/{id}/{transition:start|complete|close}")public InterventionResponse transition(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String transition,@Valid@RequestBody LifecycleInput r){PrimeHrAction action=transition.equals("close")?PrimeHrAction.FINALIZE:PrimeHrAction.APPROVE;return service.transition(agency.resolveAgencyId(a),id,r,transition,actor(a),permission.require(action,t),c);}
 @PostMapping("/interventions/{id}/checkpoints")@ResponseStatus(HttpStatus.CREATED)public InterventionResponse checkpoint(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody CheckpointInput r){return service.addCheckpoint(agency.resolveAgencyId(a),id,r,actor(a),permission.require(PrimeHrAction.EDIT,t),c);}@PostMapping("/interventions/{id}/checkpoints/{checkpointId}/complete")public InterventionResponse completeCheckpoint(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String checkpointId,@Valid@RequestBody CheckpointComplete r){return service.completeCheckpoint(agency.resolveAgencyId(a),id,checkpointId,r,actor(a),permission.require(PrimeHrAction.APPROVE,t),c);}
}
